import json

REQUIRED = json.loads('[["Кострома", 55000], ["Фудзи", 39000], ["Цусима", 32000], ["Урал", 55000], ["Пхукет", 32000]]')


def _fold(text):
    return (
        text.casefold()
        .replace("ä", "a")
        .replace("ö", "o")
        .replace("ü", "u")
        .replace("ß", "ss")
    )


def _items(payload):
    found = []
    for section in payload.get("sections"):
        if not isinstance(section, dict):
            continue
        items = section.get("items")
        if not isinstance(items, list):
            continue
        for item in items:
            if isinstance(item, dict) and isinstance(item.get("name"), str):
                found.append(item)
    return found


def run(args, state):
    raw = args.get("response")
    if not isinstance(raw, str):
        return False
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return False
    if not isinstance(payload, dict):
        return False
    sections = payload.get("sections")
    reason = payload.get("failure_reason")
    if not isinstance(sections, list) or reason != "":
        return False
    found = _items(payload)
    if len(found) == 0:
        return False
    for name, price in REQUIRED:
        needle = _fold(name)
        matched = False
        for item in found:
            item_name = _fold(item["name"])
            if needle not in item_name:
                continue
            if price is None:
                matched = True
                break
            if item.get("price_minor") == price and item.get("product_id") is None:
                matched = True
                break
        if not matched:
            return False
    return True

