def _num(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return float(value)


def _nutrition(value):
    if value is None:
        return None
    if not isinstance(value, dict):
        return None
    keys = ("calories_kcal", "proteins_g", "fats_g", "carbs_g")
    parsed = {}
    for key in keys:
        number = _num(value.get(key))
        if number is None:
            return None
        parsed[key] = number
    return parsed


def _same_item(actual, expected):
    if not isinstance(actual, dict):
        return False
    if actual.get("product_id") is not None:
        return False
    for key in ("name", "description", "price_minor", "measure", "measure_unit", "ingredients"):
        if actual.get(key) != expected[key]:
            return False
    left = _nutrition(actual.get("nutrition"))
    right = expected["nutrition"]
    if left is None or right is None:
        return left is None and right is None
    for key, number in right.items():
        if abs(left[key] - number) >= 0.001:
            return False
    return True


def run(args, state):
    raw = args.get("response")
    if not isinstance(raw, str):
        return False
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return False
    if not isinstance(payload, dict):
        return False
    sections = payload.get("sections")
    reason = payload.get("failure_reason")
    if not isinstance(sections, list) or not isinstance(reason, str):
        return False
    if reason != EXPECTED["failure_reason"]:
        return False
    expected_sections = EXPECTED["sections"]
    if len(sections) != len(expected_sections):
        return False
    for section, expected_section in zip(sections, expected_sections):
        if not isinstance(section, dict) or section.get("name") != expected_section["name"]:
            return False
        items = section.get("items")
        expected_items = expected_section["items"]
        if not isinstance(items, list) or len(items) != len(expected_items):
            return False
        for found, wanted in zip(items, expected_items):
            if not _same_item(found, wanted):
                return False
    return True

